from ext import *
ext('c10_eng_ch7',[
C("🇮🇳","अनेकता में एकता क्या है",["भाषाएँ, धर्म, पहनावा अलग","फिर भी एक साझी पहचान","भारत एक गुलदस्ते जैसा","हर फूल अपनी जगह ख़ास"],"भारत की सबसे बड़ी पहचान है अनेकता में एकता। यहाँ सैकड़ों भाषाएँ बोली जाती हैं, कई धर्मों के लोग रहते हैं और खान-पान, पहनावा और त्योहार अलग-अलग हैं। फिर भी सब मिलकर एक देश बनाते हैं। इसे एक गुलदस्ते की तरह समझिए, जिसमें अलग-अलग रंग के फूल हैं और हर फूल अपनी जगह ख़ास है, पर मिलकर गुलदस्ता सुंदर लगता है। हुमायूँ कबीर इस निबंध में बताते हैं कि यह एकता कोई बनावटी चीज़ नहीं, बल्कि हज़ारों साल की साझा विरासत से बनी है।"),
C("🏔️","भूगोल का योगदान",["उत्तर में हिमालय की दीवार","तीन ओर समुद्र","नदियाँ पूरे देश को जोड़ती हैं","प्रकृति ने एक इकाई बनाई"],"लेखक बताते हैं कि भारत की एकता में भूगोल का बहुत बड़ा हाथ है। उत्तर में ऊँचा हिमालय है और बाक़ी तीन तरफ़ समुद्र। इस तरह प्रकृति ने भारत को एक अलग क्षेत्र बना दिया। इसके अंदर बहने वाली गंगा, यमुना, कावेरी जैसी नदियाँ अलग-अलग इलाक़ों को जोड़ती हैं। हमारे बिहार की गंगा भी उसी साझा धरोहर का हिस्सा है। जब लोगों का भौगोलिक दायरा एक होता है, तो उनमें साझा अनुभव और साझा संस्कृति विकसित होती है, और यही आगे चलकर एकता का आधार बनती है।"),
C("🤝","आत्मसात करने की शक्ति",["बाहर से आए समुदाय घुल-मिल गए","नई चीज़ें अपनाईं, पुरानी नहीं छोड़ीं","भोजन, भाषा, संगीत में मिलावट","संस्कृति बहती नदी जैसी"],"निबंध की सबसे अहम बात है आत्मसात की शक्ति, यानी नई चीज़ों को अपने में मिला लेने की ताक़त। इतिहास में कई समुदाय बाहर से आए और यहीं बस गए। भारत ने उन्हें अपनाया और उन्होंने भी भारत को अपनाया। इसका नतीजा हमारे भोजन, संगीत, भाषा, कला और वास्तुकला में दिखता है। जैसे उर्दू और हिंदी का मेल, या कव्वाली और शास्त्रीय संगीत का संगम। भारतीय संस्कृति एक बहती नदी की तरह है, जो रास्ते में आने वाली धाराओं को अपने में समा लेती है और फिर भी अपनी पहचान बनाए रखती है।"),
C("🕌","साझी विरासत के उदाहरण",["ताजमहल जैसी मिली-जुली वास्तुकला","सूफ़ी और भक्ति संतों की वाणी","ईद, दिवाली, छठ साथ मनाना","हिंदी-उर्दू की साझी ज़मीन"],"भारत में साझी विरासत के कई उदाहरण हैं। वास्तुकला में भारतीय और फ़ारसी शैलियों के मेल से अद्भुत इमारतें बनीं। भक्ति और सूफ़ी संतों जैसे कबीर और अमीर ख़ुसरो ने प्रेम और भाईचारे का संदेश दिया। हमारे बिहार में भी हिंदू-मुस्लिम मिलकर त्योहार मनाते हैं, और बहुत से लोग छठ के प्रसाद या ईद की सेवइयों में एक-दूसरे को शामिल करते हैं। हिंदी और उर्दू एक ही ज़मीन से निकली दो बहनें हैं। इन उदाहरणों से पता चलता है कि हमारी संस्कृति कितनी समावेशी रही है।"),
C("🧠","हुमायूँ कबीर का परिचय",["बंगाल के शिक्षाविद् और लेखक","स्वतंत्र भारत में शिक्षा मंत्री","कवि और दार्शनिक","साझा संस्कृति के पक्षधर"],"निबंध के लेखक हुमायूँ कबीर बंगाल के एक महान शिक्षाविद्, लेखक, कवि और दार्शनिक थे। आज़ादी के बाद उन्होंने केंद्र सरकार में शिक्षा और विज्ञान से जुड़े पदों पर काम किया और भारत की शिक्षा नीति को आकार देने में योगदान दिया। उनका मानना था कि भारत की ताक़त उसकी विविधता में है, और इस विविधता को एकता में बाँधने का काम सदियों से संस्कृति करती आई है। इसी विचार को उन्होंने इस निबंध में सरल अंग्रेज़ी में रखा है। परीक्षा में लेखक का नाम, राज्य और विषय अक्सर पूछा जाता है।"),
C("⚠️","एकता के सामने चुनौतियाँ",["भाषा और क्षेत्र के नाम पर झगड़े","धार्मिक कट्टरता","अफ़वाहें और नफ़रत","समाधान: संवाद और शिक्षा"],"निबंध यह भी याद दिलाता है कि एकता अपने आप नहीं बनी रहती, उसे सँभालना पड़ता है। कई बार भाषा, क्षेत्र या धर्म के नाम पर लोगों को बाँटने की कोशिश होती है। अफ़वाहें और नफ़रत समाज में दरार डालती हैं। इसका समाधान है संवाद, अच्छी शिक्षा और दूसरों की संस्कृति का सम्मान। विद्यार्थी होने के नाते हमारी भी ज़िम्मेदारी है कि हम कभी किसी का मज़ाक उसकी भाषा, पहनावे या रंग के आधार पर न उड़ाएँ। जब हम एक-दूसरे को समझते हैं, तो फ़र्क़ सुंदरता लगता है, डर नहीं।"),
C("🎓","शिक्षा और एकता",["साझा पाठ्यक्रम और साझा मूल्य","हर भाषा का सम्मान","इतिहास की सही समझ","विद्यालय एकता की पहली सीढ़ी"],"शिक्षा समाज को जोड़ने का सबसे मज़बूत साधन है। जब विभिन्न प्रदेशों के बच्चे एक जैसी किताबें पढ़ते हैं, तो उनमें साझा समझ बनती है। विद्यालय में हर जाति, धर्म और भाषा के बच्चे साथ बैठते हैं, इसलिए स्कूल एकता की पहली पाठशाला है। हमें अपनी भाषा के साथ दूसरी भाषाएँ भी सीखनी चाहिए। जब आप किसी दूसरी भाषा का एक गीत सीखते हैं, तो उस समुदाय से आपका रिश्ता गहरा हो जाता है। इतिहास को भी सही नज़रिए से पढ़िए, ताकि आप जान सकें कि हमारी जड़ें एक-दूसरे से कितनी जुड़ी हैं।"),
C("📝","शब्दार्थ दोहराइए",["यूनिटी यानी एकता","डायवर्सिटी यानी विविधता","कल्चर यानी संस्कृति","एसिमिलेशन यानी आत्मसात"],"नए शब्द दोहराते हैं। यूनिटी यानी एकता, डायवर्सिटी यानी विविधता, कल्चर यानी संस्कृति और एसिमिलेशन यानी आत्मसात। इनके साथ हेरिटेज यानी विरासत, ट्रेडिशन यानी परंपरा और हार्मनी यानी सद्भाव भी याद कर लीजिए। अब हर शब्द से एक वाक्य बनाइए। जैसे इंडिया इज़ अ लैंड ऑफ़ डायवर्सिटी, यानी भारत विविधता की भूमि है। और यूनिटी इन डायवर्सिटी इज़ आवर स्ट्रेंथ, यानी अनेकता में एकता हमारी ताक़त है। ये वाक्य निबंध लेखन में बहुत काम आएँगे।"),
C("🧩","व्याकरण: कनेक्टर शब्द",["हाउएवर, देयरफ़ॉर, मोरओवर","एक विचार से दूसरे विचार पर जाना","निबंध को सुसंगत बनाते हैं","उदाहरण के साथ प्रयोग"],"निबंध में विचारों को जोड़ने के लिए कनेक्टर शब्द काम आते हैं। हाउएवर का मतलब है फिर भी, देयरफ़ॉर यानी इसलिए, मोरओवर यानी इसके अलावा और ऑन द अदर हैंड यानी दूसरी ओर। जैसे इंडिया हैज़ मैनी लैंग्वेजेज़। हाउएवर, इट इज़ वन नेशन। यानी भारत में कई भाषाएँ हैं, फिर भी यह एक राष्ट्र है। इन शब्दों से लेखन सुव्यवस्थित लगता है। भारतीय संस्कृति पर चार वाक्य लिखिए और हर वाक्य जोड़ने के लिए अलग कनेक्टर का प्रयोग कीजिए।"),
C("🎭","हमारे आसपास की एकता",["छठ घाट पर सब साथ","गाँव के मेले","स्कूल का सांस्कृतिक दिवस","अलग भाषाओं के गीत"],"आइए अपने आसपास की एकता देखें। छठ घाट पर हर वर्ग के लोग साथ खड़े होते हैं। गाँव के मेलों में सब मिलकर झूले झूलते हैं और मिठाइयाँ खाते हैं। हमारे स्कूल में जब सांस्कृतिक दिवस होता है, तो कोई बिहू करता है, कोई भांगड़ा, कोई छठ के गीत गाता है। हर प्रस्तुति अलग है, पर दर्शकों का उत्साह एक जैसा। यही असली भारत है। अगली बार जब आप ऐसा कार्यक्रम देखें, तो ध्यान दीजिए कि कैसे अलग-अलग रंग एक ही मंच पर सजकर और सुंदर लगते हैं।"),
C("📌","निबंध का सार",["भारत में विविधता बहुत","भूगोल और इतिहास ने जोड़ा","आत्मसात करने की शक्ति","संदेश: एकता बनाए रखें"],"अब निबंध का सार दोहरा लें। हुमायूँ कबीर कहते हैं कि भारत में भाषा, धर्म और रहन-सहन की बहुत विविधता है, फिर भी एक साझी संस्कृति सबको जोड़ती है। भूगोल और इतिहास ने इसमें अहम भूमिका निभाई। भारत की आत्मसात करने की शक्ति ने बाहर से आए तत्वों को अपने में समा लिया। संदेश यह है कि हमें अपनी विविधता पर गर्व करना चाहिए और एकता बनाए रखनी चाहिए। इसे पाँच वाक्यों में अपने शब्दों में लिखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["निबंध के लेखक कौन","भारतीय एकता के आधार","आत्मसात शक्ति का अर्थ","निबंध का संदेश"],"परीक्षा के प्रश्न देखिए। पहला, लेखक कौन हैं? उत्तर, हुमायूँ कबीर, बंगाल के शिक्षाविद्। दूसरा, भारतीय एकता के आधार क्या हैं? उत्तर, भूगोल, साझा इतिहास और संस्कृति। तीसरा, आत्मसात शक्ति का अर्थ? उत्तर, नई चीज़ों को अपने में मिला लेने की क्षमता। चौथा, संदेश? उत्तर, विविधता के बावजूद भारत एक है और हमें इस एकता को बनाए रखना चाहिए। उत्तर पूरे वाक्य में और उदाहरण के साथ लिखिए।"),
Q("आप अपने स्कूल या गाँव में एकता बनाए रखने के लिए क्या कर सकते हैं?","सबसे समान व्यवहार, दूसरों की भाषा और त्योहारों का सम्मान, और अफ़वाहों से बचना।","एक सोचने वाला प्रश्न। आप अपने स्कूल या गाँव में एकता बनाए रखने के लिए क्या कर सकते हैं? सोचिए। ... सबसे समान व्यवहार कर सकते हैं, दूसरों की भाषा और त्योहारों का सम्मान कर सकते हैं और अफ़वाहों को आगे बढ़ाने से बच सकते हैं। यही असली देशभक्ति है।"),
],7)
